'use strict';
let captured=null,freeChoices=[];
window.renderSmart=()=>{const d=$('date').value,blocks=data.blocks.filter(b=>b.date===d&&!b.done).sort((a,b)=>a.start.localeCompare(b.start)),work=entries('work').filter(x=>!x.done&&x.date<=d),family=entries('family').filter(x=>!x.done&&x.date&&x.date<=d),priority=blocks.find(b=>b.important)||work.find(x=>x.priority);$('morningTitle').textContent=d===today()?'Oggi, a colpo d’occhio':niceDate(d)+', a colpo d’occhio';$('morningBrief').textContent=`${blocks.length} impegni in programma · ${work.length} attività di lavoro · ${family.length} faccende con data.${priority?' La priorità: '+priority.title+'.':''}${blocks.length?' '+(d===today()?'Prossimo impegno: ':'Primo impegno: ')+(blocks.find(b=>d!==today()||min(b.end)>new Date().getHours()*60+new Date().getMinutes())?.title||'hai finito gli impegni con orario')+'.':''}`;};
$('captureForm').onsubmit=e=>{e.preventDefault();captured=GiornoSmart.parse($('captureText').value,today());if(!captured.title||captured.duration<5||captured.duration>720||!validTime(captured.start)){message('Non ho capito bene. Prova con “dentista domani alle 17” oppure un titolo semplice.');return;}const t=captured;$('captureSummary').textContent=`${t.title} · ${({shop:'Spesa',work:'Lavoro',family:'Famiglia',inbox:'Da incastrare',block:'Programma'})[t.kind]}${t.kind==='block'?' · '+niceDate(t.date)+(t.hasTime?' alle '+t.start:' · scegli tu l’orario'):''}`;$('captureDialog').showModal();};
$('confirmCapture').onclick=()=>{const t=captured;if(!t)return;$('captureDialog').close();if(t.kind==='block'){openEditor();$('title').value=t.title;$('blockDate').value=t.date;$('start').value=t.start;const end=Math.min(1439,min(t.start)+t.duration);$('end').value=String(Math.floor(end/60)).padStart(2,'0')+':'+String(end%60).padStart(2,'0');}else if(t.kind==='work'||t.kind==='family'){switchArea(t.kind);editDaily(t.kind);$('dailyName').value=t.title;$('dailyDate').value=t.hasDate||t.kind==='work'?t.date:'';$('workMinutes').value=t.duration;}else if(t.kind==='shop'){switchArea('shop');$('shopName').value=t.title;$('shopName').focus();message('Controlla il prodotto e premi Aggiungi.');}else editFlexible({title:t.title,duration:t.duration});$('captureText').value='';};
function renderFree(){freeChoices=GiornoSmart.nowSlots(data.inbox,data.blocks,new Date(),Number($('freeMinutes').value));$('freeResults').innerHTML=freeChoices.map((s,i)=>`<article class="slot"><div><b>${esc(s.title)}</b><span>${s.start}–${s.end}</span></div><button class="primary" data-free="${i}">Lo faccio</button></article>`).join('')||'<p class="list-empty">Non ci sono impegni compatibili adesso. Puoi lasciare libero questo tempo oppure aggiungere una cosa in “Da incastrare”.</p>';}
$('freeNow').onclick=()=>{renderFree();$('freeDialog').showModal();};$('freeMinutes').onchange=renderFree;
document.addEventListener('click',e=>{const b=e.target.closest('[data-free]');if(!b)return;const old=freeChoices[Number(b.dataset.free)],fresh=GiornoSmart.nowSlots(data.inbox,data.blocks,new Date(),Number($('freeMinutes').value)).find(x=>x.id===old?.id);if(!fresh||fresh.start!==old.start){renderFree();message('L’orario è cambiato. Controlla la nuova proposta.');return;}const n=structuredClone(data);n.blocks.push({...fresh,id:crypto.randomUUID(),kind:'task',important:false,done:false});n.inbox=n.inbox.filter(x=>x.id!==old.id);if(commit(n)){$('freeDialog').close();switchArea('today');day(today());message('È nel programma. Una cosa alla volta.');}});
$('closeDay').onclick=()=>{const d=$('date').value,items=[...data.blocks.filter(x=>x.date===d&&!x.done).map(x=>({...x,area:'blocks'})),...entries('work').filter(x=>x.date<=d&&!x.done).map(x=>({...x,area:'work'})),...entries('family').filter(x=>x.date&&x.date<=d&&!x.done).map(x=>({...x,area:'family'}))];$('closeSummary').textContent=`${niceDate(d)} · ${data.blocks.filter(x=>x.date===d&&x.done).length+entries('work').filter(x=>x.date===d&&x.done).length} attività del programma e del lavoro completate. Scegli solo quello che vuoi riprogrammare.`;$('closeChoices').innerHTML=items.map(x=>`<label class="review-row">${esc(x.title)}<select data-review="${x.area}" data-id="${esc(x.id)}"><option value="keep">Lasciala così</option><option value="tomorrow">Sposta al giorno successivo</option>${x.area==='blocks'?'<option value="inbox">Da incastrare, senza data</option>':''}</select></label>`).join('')||'<p>Non resta nulla da riprogrammare. Puoi fermarti qui.</p>';$('closeError').textContent='';$('closeDialog').showModal();};
$('confirmClose').onclick=()=>{const n=structuredClone(data),d=plus($('date').value,1);for(const el of document.querySelectorAll('[data-review]')){const k=el.dataset.review,x=(n[k]||[]).find(x=>x.id===el.dataset.id);if(!x||x.done||el.value==='keep')continue;if(el.value==='tomorrow'){if(k==='blocks'&&n.blocks.some(y=>y.id!==x.id&&y.date===d&&min(y.start)<min(x.end)&&min(x.start)<min(y.end))){$('closeError').textContent=`“${x.title}” si sovrappone a un impegno di domani. Scegli “Da incastrare” oppure lasciala così. Nessuna scelta è stata ancora salvata.`;return;}x.date=d;if(k==='blocks'){x.important=false;if(x.workShiftDay)x.workShiftDay=d;}if(k==='work')x.priority=false;}else if(el.value==='inbox'){n.inbox.push({id:crypto.randomUUID(),title:x.title,duration:Math.max(5,Math.ceil((min(x.end)-min(x.start))/5)*5)});n.blocks=n.blocks.filter(b=>b.id!==x.id);}}if(commit(n)){$('closeDialog').close();message('Scelte salvate. Il resto può aspettare.');}};
renderSmart();
